INSERT INTO kv_store (namespace, key, value, updated_at) VALUES ('global', 'admin-edit-doc-draft-36c0b1e6-d05f-4912-91f1-f261c50b5eae', '{"s35": {"detailedNotes": "<p><strong>Nabaat Care</strong> is a leading health and wellness service dedicated to providing comprehensive care and support for individuals seeking to improve their physical, emotional, and mental well-being. Our mission is to offer a holistic approach to health by combining traditional healing practices with modern healthcare solutions, ensuring that our clients receive the best possible care.</p><p>At Nabaat Care, we focus on personalized care plans tailored to meet the unique needs of each individual. Our team of experienced professionals is committed to offering a range of services designed to promote overall wellness, recovery, and a balanced lifestyle.</p><p>Whether you are looking for preventative care, post-treatment rehabilitation, or simply wish to maintain a healthy lifestyle, Nabaat Care is here to guide you every step of the way. With our compassionate approach and expertise, we are your trusted partner in achieving optimal health and well-being.</p>", "detailedNotesTitle": "Nabaat Care Introduction", "detailedNotesSubtitle": "Use this space to document any additional client requirements, discussions, or specifications in detail"}}'::jsonb, '2026-04-06T15:47:34.992Z') ON CONFLICT (namespace, key) DO UPDATE SET value = EXCLUDED.value, updated_at = EXCLUDED.updated_at;
