INSERT INTO kv_store (namespace, key, value, updated_at) VALUES ('global', 'admin-invoices', '[{"id": "0d93fb9c-3ef4-437b-8bbc-6176e463c773", "items": [{"id": "89023a48-90ac-4bb9-be97-54dc51ca57d1", "qty": "1", "sku": "", "unit": "Piece (Pc)", "notes": "", "discount": "0", "unitPrice": "70", "itemStatus": "Reserved", "productName": "iPhone"}], "notes": "", "paidAt": "", "status": "Draft", "dueDate": "2026-05-05", "taxRate": "20", "customer": "undefined undefined", "agreement": "", "createdAt": "2026-04-05T10:14:44.631Z", "updatedAt": "2026-04-05T10:14:44.631Z", "amountPaid": "", "buyerEmail": "", "buyerPhone": "", "customerId": "", "bankDetails": "", "handlingFee": "", "invoiceDate": "2026-04-05", "shippingFee": "", "buyerAddress": "", "invoiceTitle": "Tax Invoice", "paymentTerms": "", "invoiceFooter": "", "invoiceNumber": "INV-202604-001", "paymentMethod": "Bank Transfer", "stockDeducted": false, "paymentHistory": [{"id": "3ad3c8da-b89c-4818-82fe-be3b31b0a3fc", "date": "2026-04-05", "note": "", "amount": "84", "method": "Bank Transfer"}], "shippingMethod": ""}, {"id": "b3313796-b3a1-4f47-935b-2c02547b198a", "items": [{"id": "cbb9be01-014d-43d4-9dea-008d9c136fba", "qty": "1", "sku": "", "unit": "", "notes": "", "discount": "0", "unitPrice": "70", "itemStatus": "Delivered", "productName": "A"}], "notes": "", "paidAt": "", "status": "Draft", "agentId": "cf0b663a-8c11-40f8-bda2-2e7b1f51ec60", "dueDate": "2026-05-05", "taxRate": "20", "customer": "Abdul", "agentName": "Abdul Qayyum", "agreement": "", "buyerTown": "SHEIKHUPURA", "createdAt": "2026-04-05T12:33:51.967Z", "updatedAt": "2026-04-17T19:28:05.967Z", "amountPaid": "", "buyerEmail": "qayyum.mughal10@gmail.com", "buyerPhone": "+923334199233", "customerId": "", "saleStatus": "Delivered", "bankDetails": "", "handlingFee": "", "invoiceDate": "2026-04-05", "invoiceDocs": [{"id": "e666b3a1-6b7f-427c-8d68-66ee5a4bb0e4", "title": "Payment Terms", "content": "<h1>Service Agreement</h1><p>Last updated: 5 April 2026</p><p>This Service Agreement (\"Agreement\") is made between Onesoft (\"Service Provider\") and the client named in the associated Statement of Work (\"Client\").</p><h2>1. Services</h2><p>The Service Provider agrees to deliver the services described in the agreed Statement of Work. Specific deliverables, timelines, and acceptance criteria shall be set out therein.</p><h2>2. Fees and Payment</h2><p>The Client agrees to pay the fees set out in the Statement of Work. All invoices are due within 30 days of the invoice date. Overdue invoices may attract late payment interest in accordance with the Late Payment of Commercial Debts (Interest) Act 1998.</p><h2>3. Client Responsibilities</h2><p>The Client agrees to provide timely access to systems, information, and personnel as reasonably required for the Service Provider to perform the services.</p><h2>4. Warranties</h2><p>The Service Provider warrants that services will be performed with reasonable skill and care in accordance with industry standards.</p><h2>5. Limitation of Liability</h2><p>The total liability of the Service Provider shall not exceed the total fees paid under this Agreement in the 3 months preceding the relevant claim.</p><h2>6. Termination</h2><p>Either party may terminate this Agreement with 30 days written notice. In the event of material breach, either party may terminate immediately upon written notice.</p><h2>7. Governing Law</h2><p>This Agreement is governed by the laws of England and Wales.</p>"}, {"id": "3cf79f3c-4639-41d1-a2c6-28aa83baba60", "title": "Agreement", "content": "<h1>Privacy Policy</h1><p>Last updated: 5 April 2026</p><h2>1. Who We Are</h2><p>Onesoft (\"we\", \"us\", \"our\") is a software and IT solutions company operating from Hull, UK and Islamabad, Pakistan. We are committed to protecting your personal data in accordance with the UK General Data Protection Regulation (UK GDPR) and the Data Protection Act 2018.</p><h2>2. Data We Collect</h2><p>We may collect and process the following categories of personal data: name and contact details, company information, correspondence and communication records, payment and billing information, and data provided through our software systems.</p><h2>3. How We Use Your Data</h2><p>We use your personal data to: deliver our agreed services, process invoices and payments, communicate with you about your account, comply with legal obligations, and improve our services.</p><h2>4. Legal Basis</h2><p>We process your personal data on the basis of: contract performance, legitimate business interests, legal compliance, and where applicable, your explicit consent.</p><h2>5. Data Retention</h2><p>We retain personal data only for as long as necessary to fulfil the purposes for which it was collected, or as required by applicable law. Financial records are typically retained for 7 years.</p><h2>6. Your Rights</h2><p>Under UK GDPR, you have the right to: access your personal data, correct inaccurate data, request erasure (\"right to be forgotten\"), object to processing, and data portability. To exercise these rights, please contact us in writing.</p><h2>7. Transfers Outside the UK</h2><p>Where we transfer data to our Islamabad office, we ensure appropriate safeguards are in place in accordance with UK GDPR Chapter V requirements.</p><h2>8. Contact</h2><p>For data protection queries, please contact our Data Controller at our Hull, UK office.</p>"}, {"id": "1ae3d0a7-5600-42ef-84f4-4bf4328d44b1", "title": "Additional Notes", "content": "<h1>Privacy Policy</h1><p>Last updated: 5 April 2026</p><h2>1. Who We Are</h2><p>Onesoft (\"we\", \"us\", \"our\") is a software and IT solutions company operating from Hull, UK and Islamabad, Pakistan. We are committed to protecting your personal data in accordance with the UK General Data Protection Regulation (UK GDPR) and the Data Protection Act 2018.</p><h2>2. Data We Collect</h2><p>We may collect and process the following categories of personal data: name and contact details, company information, correspondence and communication records, payment and billing information, and data provided through our software systems.</p><h2>3. How We Use Your Data</h2><p>We use your personal data to: deliver our agreed services, process invoices and payments, communicate with you about your account, comply with legal obligations, and improve our services.</p><h2>4. Legal Basis</h2><p>We process your personal data on the basis of: contract performance, legitimate business interests, legal compliance, and where applicable, your explicit consent.</p><h2>5. Data Retention</h2><p>We retain personal data only for as long as necessary to fulfil the purposes for which it was collected, or as required by applicable law. Financial records are typically retained for 7 years.</p><h2>6. Your Rights</h2><p>Under UK GDPR, you have the right to: access your personal data, correct inaccurate data, request erasure (\"right to be forgotten\"), object to processing, and data portability. To exercise these rights, please contact us in writing.</p><h2>7. Transfers Outside the UK</h2><p>Where we transfer data to our Islamabad office, we ensure appropriate safeguards are in place in accordance with UK GDPR Chapter V requirements.</p><h2>8. Contact</h2><p>For data protection queries, please contact our Data Controller at our Hull, UK office.</p>"}], "shippingFee": "", "buyerAddress": "Sabri Road Mohallah Rasool Pura", "invoiceTitle": "Tax Invoice", "paymentTerms": "", "invoiceFooter": "", "invoiceNumber": "INV-202604-002", "paymentMethod": "Bank Transfer", "stockDeducted": false, "paymentHistory": [], "shippingMethod": ""}, {"id": "e3e8b778-7e00-4ee3-a9ec-44f4ad520ca7", "jeId": "8fb6d871-469a-4274-9a6e-4b10b3f0aee0", "items": [{"id": "5c8f9f20-ec40-47a0-8832-10bbbf7088ae", "qty": "1000", "sku": "AWHI-7208", "unit": "", "notes": "", "discount": "0", "localName": "", "unitPrice": "32", "itemStatus": "Delivered", "productName": "A", "discountType": "pct", "variantLabel": "Colour: White"}], "note